import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.DFlFRONG.js";const u=JSON.parse('{"title":"About TeamOne Proxy Server","description":"","frontmatter":{},"headers":[],"relativePath":"proxy-server/index.md","filePath":"proxy-server/index.md"}'),i={name:"proxy-server/index.md"};function o(l,e,r,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="about-teamone-proxy-server" tabindex="-1">About TeamOne Proxy Server <a class="header-anchor" href="#about-teamone-proxy-server" aria-label="Permalink to &quot;About TeamOne Proxy Server&quot;">​</a></h1><p>TeamOne Proxy Server enables TeamOne for Google Sheets to connect securely to IBM Planning Analytics (TM1) environments that are not directly accessible from the user&#39;s browser.</p><p>It is typically used with IBM Planning Analytics Local when:</p><ul><li>IBM Planning Analytics is hosted inside a private corporate network</li><li>access to TM1 must be routed through a customer-controlled network endpoint</li><li>browser-compatible communication with the TM1 REST API is required</li><li>IBM Planning Analytics uses Cognos-based single sign-on</li><li>the customer wants to restrict and control which TM1 systems TeamOne can access</li></ul><p>The TeamOne Proxy Server is deployed and managed within the customer&#39;s own infrastructure. Succeedium does not host the customer&#39;s TeamOne Proxy Server or IBM Planning Analytics data.</p><h2 id="how-teamone-proxy-server-works" tabindex="-1">How TeamOne Proxy Server Works <a class="header-anchor" href="#how-teamone-proxy-server-works" aria-label="Permalink to &quot;How TeamOne Proxy Server Works&quot;">​</a></h2><p>TeamOne runs inside Google Sheets and communicates with IBM Planning Analytics through the user&#39;s browser session.</p><p>For IBM Planning Analytics Local deployments, the communication flow is typically:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Google Sheets / User Browser</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>TeamOne for Google Sheets</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>HTTPS</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>TeamOne Proxy Server</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>TM1 REST API</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>IBM Planning Analytics / TM1</span></span></code></pre></div><p>The TeamOne Proxy Server acts as a controlled communication layer between TeamOne and IBM Planning Analytics.</p><p>It is responsible for:</p><ul><li>forwarding approved requests to IBM Planning Analytics / TM1</li><li>supporting browser-compatible communication and CORS handling</li><li>supporting authentication and SSO flows where applicable</li><li>restricting proxy requests to approved TM1 hosts</li><li>providing centralized request handling and logging</li></ul><p>The TeamOne Proxy Server does not provide independent access to IBM Planning Analytics and does not replace the IBM Planning Analytics security model.</p><p>All TM1 requests remain subject to the authenticated user&#39;s IBM Planning Analytics permissions.</p><h2 id="data-and-security" tabindex="-1">Data and Security <a class="header-anchor" href="#data-and-security" aria-label="Permalink to &quot;Data and Security&quot;">​</a></h2><p>The TeamOne Proxy Server does not persist IBM Planning Analytics cube data.</p><p>Data is forwarded between TeamOne and IBM Planning Analytics in real time and exists within the proxy only for the duration of the request.</p><p>Access remains controlled by multiple security layers:</p><ul><li>Google Workspace authentication</li><li>Google Sheets document permissions</li><li>TeamOne configuration permissions</li><li>IBM Planning Analytics authentication</li><li>IBM Planning Analytics authorization and data security</li><li>customer network and infrastructure controls</li><li>TeamOne Proxy Server allowed-host restrictions</li></ul><h2 id="deployment-models" tabindex="-1">Deployment Models <a class="header-anchor" href="#deployment-models" aria-label="Permalink to &quot;Deployment Models&quot;">​</a></h2><p>TeamOne Proxy Server supports two common SSL/TLS deployment models.</p><h3 id="ssl-managed-by-a-load-balancer" tabindex="-1">SSL Managed by a Load Balancer <a class="header-anchor" href="#ssl-managed-by-a-load-balancer" aria-label="Permalink to &quot;SSL Managed by a Load Balancer&quot;">​</a></h3><p>In this model, the customer manages the SSL/TLS certificate on a load balancer.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Browser</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTPS / TLS 443</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Customer Load Balancer</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTP 80</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>TeamOne Proxy Server</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>IBM Planning Analytics / TM1</span></span></code></pre></div><p>The load balancer provides the externally accessible HTTPS endpoint and forwards trusted internal HTTP traffic to the TeamOne Proxy Server.</p><p>This model is commonly used in AWS and other enterprise cloud environments because certificate management and renewal can remain within the customer&#39;s existing infrastructure.</p><p>TeamOne Proxy Server uses TCP port <code>80</code> as the default HTTP listener port when SSL/TLS is managed by a load balancer.</p><p>Refer to the following Nginx configuration template to manage the default HTTP listener and related proxy settings:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config/nginx-http.conf.example</span></span></code></pre></div><p>See the full installation guide:</p><p><a href="./installation-load-balancer-ssl.html">TeamOne Installation Guide – SSL Managed by Load Balancer</a></p><h3 id="ssl-managed-by-teamone-proxy-server" tabindex="-1">SSL Managed by TeamOne Proxy Server <a class="header-anchor" href="#ssl-managed-by-teamone-proxy-server" aria-label="Permalink to &quot;SSL Managed by TeamOne Proxy Server&quot;">​</a></h3><p>In this model, the SSL/TLS certificate and private key are installed directly on the TeamOne Proxy Server.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User Browser</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>HTTPS / TLS 443</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>TeamOne Proxy Server</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>IBM Planning Analytics / TM1</span></span></code></pre></div><p>The TeamOne Proxy Server terminates HTTPS directly and manages the certificate files used by Nginx.</p><p>TeamOne Proxy Server uses TCP port <code>443</code> as the default HTTPS listener port when SSL/TLS certificates are installed and managed directly on the TeamOne Proxy Server.</p><p>Refer to the following Nginx configuration template to manage the default HTTPS listener and related SSL/TLS settings:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config/nginx-https.conf.example</span></span></code></pre></div><p>A load balancer can still be used in front of the TeamOne Proxy Server in this deployment model. In that case, the load balancer forwards HTTPS traffic to the TeamOne Proxy Server, while the SSL/TLS certificate and private key remain installed and managed directly on the TeamOne Proxy Server.</p><p>See the full installation guide:</p><p><a href="./installation-direct-ssl.html">Installation Guide – SSL Managed by TeamOne Proxy Server</a></p><h2 id="choosing-a-deployment-model" tabindex="-1">Choosing a Deployment Model <a class="header-anchor" href="#choosing-a-deployment-model" aria-label="Permalink to &quot;Choosing a Deployment Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>SSL Managed by Load Balancer</th><th>SSL Managed by TeamOne Proxy Server</th></tr></thead><tbody><tr><td>SSL certificate managed on</td><td>Customer load balancer</td><td>TeamOne Proxy Server</td></tr><tr><td>External connection</td><td>HTTPS / TLS 443</td><td>HTTPS / TLS 443</td></tr><tr><td>TeamOne Proxy listener</td><td>HTTP 80 by default</td><td>HTTPS 443</td></tr><tr><td>Nginx configuration</td><td><code>nginx-http.conf.example</code></td><td><code>nginx-https.conf.example</code></td></tr><tr><td>Certificate files required on Proxy Server</td><td>No</td><td>Yes</td></tr><tr><td>Centralized certificate renewal</td><td>Yes</td><td>Customer-managed on Proxy Server</td></tr><tr><td>Typical use</td><td>AWS / enterprise infrastructure</td><td>Standalone or direct deployment</td></tr></tbody></table><p>For AWS and other environments that already use centralized load balancers and certificate management, the load balancer model is generally the simpler deployment.</p><h2 id="ssl-tls-certificates" tabindex="-1">SSL/TLS Certificates <a class="header-anchor" href="#ssl-tls-certificates" aria-label="Permalink to &quot;SSL/TLS Certificates&quot;">​</a></h2><p>The external TeamOne Proxy endpoint must use HTTPS.</p><p>The load balancer or TeamOne Proxy Server may use:</p><ul><li>a publicly trusted SSL/TLS certificate</li><li>a certificate issued by the customer&#39;s internal Certificate Authority (CA)</li><li>a self-signed certificate</li></ul><p>For internal CA or self-signed certificates, the required certificate trust must be established on users&#39; devices and browsers through the customer&#39;s standard IT or device-management processes.</p><p>If the browser does not trust the certificate presented by the TeamOne endpoint, TeamOne connections may fail.</p><h2 id="public-address-space-requirement" tabindex="-1">Public Address-Space Requirement <a class="header-anchor" href="#public-address-space-requirement" aria-label="Permalink to &quot;Public Address-Space Requirement&quot;">​</a></h2><p>The TeamOne Proxy Server endpoint must resolve to an IP address that the browser treats as belonging to public address space.</p><p>This requirement is related to browser Local Network Access security restrictions when Google Sheets communicates with customer-hosted services.</p><p>The endpoint does not need to be openly accessible from the public internet.</p><p>Customers can restrict access using controls such as:</p><ul><li>corporate source IP ranges</li><li>VPN egress ranges</li><li>Zscaler or equivalent secure access services</li><li>load balancer security rules</li><li>AWS security groups</li><li>firewall policies</li></ul><p>The important distinction is that the TeamOne endpoint must use public address space while access to that endpoint can still be restricted to approved users and network paths.</p><h2 id="network-access" tabindex="-1">Network Access <a class="header-anchor" href="#network-access" aria-label="Permalink to &quot;Network Access&quot;">​</a></h2><p>A typical deployment separates inbound and outbound access.</p><h3 id="inbound-access" tabindex="-1">Inbound Access <a class="header-anchor" href="#inbound-access" aria-label="Permalink to &quot;Inbound Access&quot;">​</a></h3><p>Users access the TeamOne endpoint through their browser.</p><p>For load-balancer deployments:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Approved User Network</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>HTTPS / TLS 443</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Customer Load Balancer</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>HTTP 80</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>TeamOne Proxy Server</span></span></code></pre></div><p>The TeamOne Proxy Server should not normally be directly accessible from the public internet.</p><p>Inbound access to the proxy should be limited to the approved load balancer or other customer-managed network path.</p><h3 id="outbound-access" tabindex="-1">Outbound Access <a class="header-anchor" href="#outbound-access" aria-label="Permalink to &quot;Outbound Access&quot;">​</a></h3><p>The TeamOne Proxy Server must be able to communicate with the IBM Planning Analytics / TM1 REST API endpoints configured in TeamOne.</p><p>TM1 environments commonly run multiple TM1 instances using different REST API ports.</p><p>Customers can restrict outbound access by:</p><ul><li>approved TM1 hostname or IP address</li><li>approved TM1 REST API ports</li><li>both hostname/IP and port</li></ul><p>Where multiple TM1 instances use different ports, customers may choose to restrict access by approved TM1 hosts/IPs and use TeamOne&#39;s application-level allowed-host configuration as an additional security control.</p><h2 id="allowed-host-configuration" tabindex="-1">Allowed Host Configuration <a class="header-anchor" href="#allowed-host-configuration" aria-label="Permalink to &quot;Allowed Host Configuration&quot;">​</a></h2><p>TeamOne Proxy Server includes application-level controls that restrict which hosts can be accessed through the proxy.</p><p>These settings are configured in:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>teamone-server-distr/config/.env</span></span></code></pre></div><h3 id="tm1-hosts" tabindex="-1">TM1 Hosts <a class="header-anchor" href="#tm1-hosts" aria-label="Permalink to &quot;TM1 Hosts&quot;">​</a></h3><p><code>PROXY_ALLOWED_HOST_PATTERN</code> controls which IBM Planning Analytics / TM1 hosts can be accessed through the TeamOne proxy.</p><p>Example using specific hosts:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=tm1-prod.internal.company.com,tm1-dev.internal.company.com</span></span></code></pre></div><p>A wildcard can also be used for a trusted internal domain:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=*.internal.company.com</span></span></code></pre></div><p>Avoid overly broad patterns such as:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*.com</span></span></code></pre></div><p>in production environments.</p><h2 id="cognos-sso-oauth-hosts" tabindex="-1">Cognos SSO / OAuth Hosts <a class="header-anchor" href="#cognos-sso-oauth-hosts" aria-label="Permalink to &quot;Cognos SSO / OAuth Hosts&quot;">​</a></h2><p><code>PROXY_OAUTH_ALLOWED_HOST_PATTERN</code> controls which hosts can be used by TeamOne OAuth/SSO endpoints.</p><p>These include:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/oauth/login/</span></span>
<span class="line"><span>/oauth/token/</span></span>
<span class="line"><span>/oauth/logout/</span></span></code></pre></div><p>For IBM Planning Analytics Local using Cognos authentication, this should normally contain the Cognos Gateway hostname configured in the <code>ClientCAMURI</code> parameter in <code>tm1s.cfg</code>.</p><p>For example:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ClientCAMURI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://cognos.company.com/ibmcognos/bi/v1/disp</span></span></code></pre></div><p>Configure:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cognos.company.com</span></span></code></pre></div><p>Use the hostname only, not the full URL or path.</p><p>Multiple hosts can be separated with commas:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cognos-prod.company.com,cognos-qa.company.com</span></span></code></pre></div><p>Wildcard patterns are also supported:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=*.company.com</span></span></code></pre></div><p>If Cognos SSO is not used, configure a non-matching value:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PROXY_OAUTH_ALLOWED_HOST_PATTERN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=disabled.local</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>TeamOne supports IBM Planning Analytics Local environments with and without SSO.</p><h3 id="without-sso" tabindex="-1">Without SSO <a class="header-anchor" href="#without-sso" aria-label="Permalink to &quot;Without SSO&quot;">​</a></h3><p>Users authenticate using the IBM Planning Analytics authentication method configured for the TM1 server.</p><p>The TeamOne Proxy Server forwards the authenticated requests to IBM Planning Analytics.</p><p>IBM Planning Analytics remains responsible for validating the user and enforcing all security permissions.</p><h3 id="with-cognos-sso" tabindex="-1">With Cognos SSO <a class="header-anchor" href="#with-cognos-sso" aria-label="Permalink to &quot;With Cognos SSO&quot;">​</a></h3><p>For environments using IBM Cognos-based authentication, TeamOne can support the existing Cognos login flow.</p><p>The TeamOne Proxy Server facilitates communication between TeamOne, the Cognos Gateway, the customer&#39;s identity provider, and IBM Planning Analytics.</p><p>The existing customer identity provider may include services such as:</p><ul><li>Microsoft Entra ID</li><li>Google Cloud Identity</li><li>Okta</li><li>other identity providers integrated with IBM Cognos Analytics</li></ul><p>After authentication, IBM Planning Analytics continues to enforce the authenticated user&#39;s TM1 security permissions.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Choose the guide that matches your deployment model:</p><h3 id="new-installation" tabindex="-1">New Installation <a class="header-anchor" href="#new-installation" aria-label="Permalink to &quot;New Installation&quot;">​</a></h3><ul><li><a href="./installation-load-balancer-ssl.html">Installation Guide – SSL Managed by Load Balancer</a></li><li><a href="./installation-direct-ssl.html">Installation Guide – SSL Managed by TeamOne Proxy Server</a></li></ul><h3 id="existing-installation" tabindex="-1">Existing Installation <a class="header-anchor" href="#existing-installation" aria-label="Permalink to &quot;Existing Installation&quot;">​</a></h3><ul><li><a href="./upgrade-load-balancer-ssl.html">Upgrade Guide – SSL Managed by Load Balancer</a></li><li><a href="./upgrade-direct-ssl.html">Upgrade Guide – SSL Managed by TeamOne Proxy Server</a></li></ul><p>For questions or assistance with TeamOne Proxy Server deployment, contact:</p><p><strong><a href="mailto:teamone@succeedium.com" target="_blank" rel="noreferrer">teamone@succeedium.com</a></strong></p>`,120)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
